{
  "name": "opencode-websearch-addons",
  "version": "1.1.0",
  "description": "OpenCode V2 plugin that adds OpenAI and Gemini native web search providers to the built-in websearch tool.",
  "homepage": "https://github.com/gotenksIN/opencode-websearch-addons",
  "license": "MIT",
  "author": {
    "name": "Omkar Chandorkar",
    "email": "gotenksIN@aospa.co"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/gotenksIN/opencode-websearch-addons.git"
  },
  "files": [
    "dist",
    "index.ts",
    "src"
  ],
  "type": "module",
  "main": "./dist/index.js",
  "exports": {
    ".": "./dist/index.js",
    "./source": "./index.ts"
  },
  "scripts": {
    "lint": "oxlint --type-aware .",
    "format": "oxfmt --write .",
    "test": "bun test",
    "test:agent": "AGENT=1 bun test --bail",
    "test:live": "bun test tests/live.test.ts",
    "typecheck": "tsc --noEmit",
    "check": "oxlint --type-aware . && oxfmt --check . && tsc --noEmit && bun test",
    "prepack": "bun run build",
    "build": "bun build index.ts --outdir dist --target bun --format esm --external @opencode/plugin --external effect"
  },
  "devDependencies": {
    "@opencode/core": "latest",
    "@opencode/plugin": "latest",
    "@types/bun": "1.4.4",
    "effect": "4.1.0",
    "oxfmt": "^0.78.0",
    "oxlint": "^1.93.0",
    "oxlint-tsgolint": "^7.0.2007",
    "typescript": "7.0.2",
    "ultracite": "^8.2.0"
  },
  "peerDependencies": {
    "@opencode/plugin": "^2.3.0",
    "effect": "^4.0.0"
  },
  "engines": {
    "bun": ">=1.2.0"
  }
}

import { Plugin } from "@opencode/plugin";

import { parseConfig } from "./src/config.js";
import { searchGoogle } from "./src/google.js";
import { searchOpenAI } from "./src/openai.js";

export default Plugin.define({
  id: "opencode-websearch-addons",
  async setup(ctx) {
    const config = parseConfig(ctx.options);

    const registration = await ctx.websearch.transform((draft) => {
      draft.add({
        id: "openai",
        name: "OpenAI Web Search",
        execute: async ({ query }, { signal }) =>
          await searchOpenAI(
            ctx,
            config.openai,
            config.timeoutMs,
            query,
            signal
          ),
      });
      draft.add({
        id: "google",
        name: "Gemini Google Search",
        execute: async ({ query }, { signal }) =>
          await searchGoogle(
            ctx,
            config.google,
            config.timeoutMs,
            query,
            signal
          ),
      });
    });

    return async () => {
      await registration.dispose();
    };
  },
});
